export const AUTHORIZATION =
  "Each call must be reviewed and signed by the user's own wallet, in order. Vessel never holds keys or submits transactions.";

/** Quote validity for preparations with no on-chain deadline. */
export const QUOTE_TTL_SEC = 15 * 60;

const controllerAbi = parseAbi([
  "function requestDeposit(uint8 tranche, uint256 seriesId, uint256 assets, address receiver, uint256 minOut, uint256 deadline) returns (uint256)",
  "function cancelDeposit(uint256 id)",
  "function claimRefund(uint256 id)",
  "function requestBallastRedeem(uint256 units, address receiver, uint256 minAssets) returns (uint256)",
  "function cancelRedeem(uint256 id)",
  "function claimHull(uint256 seriesId) returns (uint256)",
]);
const erc20Abi = parseAbi(["function approve(address spender, uint256 amount) returns (bool)"]);
const escrowAbi = parseAbi(["function claim(bytes32 key) returns (uint256)"]);

export type PreparedCall = {
  to: Address;
  data: Hex;
  value: "0";
  function: string;
  description: string;
};

export type Prepared = {
  intent: string;
  chainId: number;
  calls: PreparedCall[];
  authorization: string;
  /** Unix seconds (decimal string) after which this preparation must not be signed. */
  expiresAt: string;
  notes: string[];
};

export class PrepareError extends Error {}

function addr(m: Manifest, name: string): Address {
  const a = m.contracts[name];
  if (!a || !isAddress(a)) throw new PrepareError(`release manifest has no ${name}`);
  return getAddress(a);
}

function owner(x: string): Address {
  if (!isAddress(x)) throw new PrepareError("owner must be a valid address");
  const a = getAddress(x);
  if (a === "0x0000000000000000000000000000000000000000") throw new PrepareError("owner must not be the zero address");
  return a;
}

function positive(x: bigint, what: string): bigint {
  if (x <= 0n) throw new PrepareError(`${what} must be greater than zero`);
  return x;
}

const ttl = (now: number) => BigInt(now) + BigInt(QUOTE_TTL_SEC);

export const exitKey = (id: bigint) =>
  keccak256(encodeAbiParameters([{ type: "string" }, { type: "uint256" }], ["VESSEL_EXIT", id]));

function approveCall(m: Manifest, assets: bigint): PreparedCall {
  const custody = addr(m, "AssetCustody");
  return {
    to: addr(m, "DemoUSD"),
    data: encodeFunctionData({ abi: erc20Abi, functionName: "approve", args: [custody, assets] }),
    value: "0",
    function: "approve(address,uint256)",
    description: `Approve exactly ${assets} base units for AssetCustody ${custody} (custody pulls the deposit).`,
  };
}

function controllerCall(m: Manifest, functionName: (typeof controllerAbi)[number]["name"], args: readonly unknown[], description: string): PreparedCall {
  return {
    to: addr(m, "TrancheController"),
    data: encodeFunctionData({ abi: controllerAbi, functionName, args } as never),
    value: "0",
    function: functionName,
    description,
  };
}

type DepositArgs = {
  manifest: Manifest;
  owner: string;
  assets: bigint;
  deadline: bigint;
  now: number;
  /** Current dUSD allowance to AssetCustody; the approve step is skipped only when it already covers `assets`. */
  currentAllowance?: bigint;
};

function deposit(a: DepositArgs, tranche: 0 | 1, seriesId: bigint, minOut: bigint, intent: string, label: string): Prepared {
  const who = owner(a.owner);
  const assets = positive(a.assets, "assets");
  if (a.deadline <= BigInt(a.now)) throw new PrepareError("deadline must be in the future");
  const calls: PreparedCall[] = [];
  if ((a.currentAllowance ?? 0n) < assets) calls.push(approveCall(a.manifest, assets)); // rule0-ok: unknown allowance means approve
  calls.push(
    controllerCall(
      a.manifest,
      "requestDeposit",
      [tranche, seriesId, assets, who, minOut, a.deadline],
      `${label}: request ${assets} base units for ${who}. Not admitted by the deadline → refundable.`,
    ),
  );
  return {
    intent,
    chainId: a.manifest.chainId,
    calls,
    authorization: AUTHORIZATION,
    expiresAt: (a.deadline < ttl(a.now) ? a.deadline : ttl(a.now)).toString(),
    notes: [
      "A deposit is a request: units are minted only on admission.",
      "Approval and request are separate transactions; sign them in order.",
    ],
  };
}

/** Ballast deposit request. `minUnits` is the minimum Ballast units accepted at admission. */
export const prepareBallastDeposit = (a: DepositArgs & { minUnits: bigint }) =>
  deposit(a, 1, 0n, a.minUnits, "ballast_deposit", "Ballast");

/** Hull subscription to an open series. `minRateBps` should equal the series' published rate. */
export const prepareHullSubscription = (a: DepositArgs & { seriesId: bigint; minRateBps: bigint }) =>
  deposit(a, 0, positive(a.seriesId, "seriesId"), positive(a.minRateBps, "minRateBps"), "hull_subscription", `Hull series ${a.seriesId}`);

function single(m: Manifest, now: number, intent: string, call: PreparedCall, notes: string[] = []): Prepared {
  return { intent, chainId: m.chainId, calls: [call], authorization: AUTHORIZATION, expiresAt: ttl(now).toString(), notes };
}

export function prepareBallastExit(a: { manifest: Manifest; owner: string; units: bigint; minAssets: bigint; now: number }): Prepared {
  const who = owner(a.owner);
  return single(
    a.manifest,
    a.now,
    "ballast_exit",
    controllerCall(a.manifest, "requestBallastRedeem", [positive(a.units, "units"), who, a.minAssets], `Lock ${a.units} Ballast units into an exit paid to ${who}.`),
    ["Exits wait a 48-hour cooldown, then fill in order as liquidity and 30% cover allow — possibly in parts.", "Units stay exposed until filled."],
  );
}

